import{_ as e,o,c as n,ah as a}from"./chunks/framework.Cq2CPxk9.js";const i="/projects/AiNova/en/latest/assets/image2.C7OIxKJz.png",s="/projects/AiNova/en/latest/assets/image3.BIx1rvj2.png",r="/projects/AiNova/en/latest/assets/image4.DsS5N_kJ.png",l="/projects/AiNova/en/latest/assets/image2.Ca6HXT-2.png",c="/projects/AiNova/en/latest/assets/image3.Cd6V3jpT.png",d="/projects/AiNova/en/latest/assets/image4.D2aEEw2t.png",h="/projects/AiNova/en/latest/assets/image5.ByhJX2rZ.png",g="/projects/AiNova/en/latest/assets/image6.ZI3sMS0x.png",p="/projects/AiNova/en/latest/assets/image7.BWUHxuI4.png",m="/projects/AiNova/en/latest/assets/image8.CzpdoYsh.png",u="/projects/AiNova/en/latest/assets/image9.Cb8A8Qmz.png",b="/projects/AiNova/en/latest/assets/image10.IrDz_IWq.png",_="/projects/AiNova/en/latest/assets/image11.CzFIdRMr.png",f="/projects/AiNova/en/latest/assets/image12.CSjxfdLs.png",y="/projects/AiNova/en/latest/assets/image13.Dnnyn-Vd.png",v="/projects/AiNova/en/latest/assets/image14.CB5Grmzd.png",w="/projects/AiNova/en/latest/assets/image15.B_M6YNct.png",x="/projects/AiNova/en/latest/assets/image16.BzHglZWZ.png",A="/projects/AiNova/en/latest/assets/image17.UQ6DXBfe.png",N="/projects/AiNova/en/latest/assets/image18.D62wxqT4.png",q="/projects/AiNova/en/latest/assets/image19.XKAvRz2o.png",P="/projects/AiNova/en/latest/assets/image5.Bs24960H.png",B=JSON.parse('{"title":"4. APP Remote Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/4.app_remote_control.md","filePath":"docs/4.app_remote_control.md"}'),k={name:"docs/4.app_remote_control.md"};function z(j,t,T,S,C,I){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="_4-app-remote-control" tabindex="-1">4. APP Remote Control <a class="header-anchor" href="#_4-app-remote-control" aria-label="Permalink to &quot;4. APP Remote Control&quot;">​</a></h1><h2 id="_4-1-app-installation-and-connection-instructions" tabindex="-1">4.1 APP Installation and Connection Instructions <a class="header-anchor" href="#_4-1-app-installation-and-connection-instructions" aria-label="Permalink to &quot;4.1 APP Installation and Connection Instructions&quot;">​</a></h2><h3 id="_4-1-1-app-installation" tabindex="-1">4.1.1 APP Installation <a class="header-anchor" href="#_4-1-1-app-installation" aria-label="Permalink to &quot;4.1.1 APP Installation&quot;">​</a></h3><p>For Android Users: You can find the installation package in this section&#39;s directory or click <a href="https://play.google.com/store/apps/details?id=com.hiwonder.wondercom" target="_blank" rel="noreferrer">WonderCom</a>. Transfer it to your phone and install it.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Make sure to enable all required permissions for the app in your phone settings to ensure proper functionality.</p></section><p>For iOS Users: Search for <a href="https://apps.apple.com/us/app/wondercom/id6446349138" target="_blank" rel="noreferrer">WonderCom</a> in the App Store and install it.</p><p>Before using the app, please enable GPS location and Bluetooth on your phone.</p><h3 id="_4-1-2-device-connection" tabindex="-1">4.1.2 Device Connection <a class="header-anchor" href="#_4-1-2-device-connection" aria-label="Permalink to &quot;4.1.2 Device Connection&quot;">​</a></h3><p>(1) Place the AiNova robot on a flat surface and turn it off and then back on.</p><p>(2) Open the WonderCom app on your phone and tap on <strong>&quot;AiNova&quot;.</strong></p><img loading="lazy" height="588" width="1267" class="common_img" src="'+i+'"><p>(3) Tap the blinking Bluetooth icon in the top-right corner of the main interface. On the search screen, select the device labeled &quot;<strong>AiNova-</strong>&quot;. As shown below:</p><img loading="lazy" height="536" width="1161" class="common_img" src="'+s+'"><p>(4) Once connected successfully, the Bluetooth icon will remain lit and display the battery level indicator.</p><img loading="lazy" height="405" width="1160" class="common_img" src="'+r+'"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Mode</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">Assembly</td><td style="text-align:center;">Provides tutorials for assembling the AiNova robot.</td></tr><tr><td style="text-align:center;">Control</td><td style="text-align:center;">Enables quick control and AI vision feature demo.</td></tr><tr><td style="text-align:center;">Programming</td><td style="text-align:center;">Allows block-based programming using built-in code blocks.</td></tr></tbody></table><h2 id="_4-2-app-user-guide" tabindex="-1">4.2 APP User Guide <a class="header-anchor" href="#_4-2-app-user-guide" aria-label="Permalink to &quot;4.2 APP User Guide&quot;">​</a></h2><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Before using the APP to control AiNova, please ensure the factory program has been downloaded. Without it, the robot cannot be controlled.</p></section><h3 id="_4-2-1-robot-control" tabindex="-1">4.2.1 Robot Control <a class="header-anchor" href="#_4-2-1-robot-control" aria-label="Permalink to &quot;4.2.1 Robot Control&quot;">​</a></h3><p>(1) Tap the corresponding icon <img loading="lazy" height="190" width="179" src="'+l+'" style="width:70px;"> on the main screen to enter the <strong>&quot;AiNova Control&quot;</strong> interface.</p><img loading="lazy" height="573" width="1238" class="common_img" src="'+c+'"><p>(2) Function descriptions for each icon are listed below:</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="191" width="207" src="'+d+'"></td><td style="text-align:center;">Control AiNova to move forward, backward, or turn.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="62" width="248" src="'+h+'"></td><td style="text-align:center;">When enabled, AiNova can be moved using the phone&#39;s gravity sensing.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="52" width="361" src="'+g+'"></td><td style="text-align:center;">When enabled, AiNova will perform obstacle avoidance using the ultrasonic sensor.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="129" width="221" src="'+p+'"></td><td style="text-align:center;">Displays the distance between the ultrasonic sensor and the object in front of it. Only works when obstacle avoidance is enabled.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="99" width="334" src="'+m+'"></td><td style="text-align:center;">Used to adjust the threshold for obstacle avoidance. Only works when obstacle avoidance is enabled.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="39" width="219" src="'+u+'"></td><td style="text-align:center;">Turns the RGB lights on or off.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="218" width="216" src="'+b+'"></td><td style="text-align:center;">Use the slider to change the RGB light color on AiNova.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="71" width="237" src="'+_+'"></td><td style="text-align:center;">Tap to connect/disconnect the Bluetooth device. Once connected, it also displays the battery level.</td></tr></tbody></table><h3 id="_4-2-2-line-tracking" tabindex="-1">4.2.2 Line tracking <a class="header-anchor" href="#_4-2-2-line-tracking" aria-label="Permalink to &quot;4.2.2 Line tracking&quot;">​</a></h3><p>(1) Tap the corresponding icon <img loading="lazy" height="171" width="135" src="'+f+'" style="width:70px;"> on the main screen to enter the <strong>&quot;Line tracking&quot;</strong> interface.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The robot may deviate when moving in a straight line. This is due to mechanical bias and is a normal phenomenon. You can reduce the deviation by adjusting the differential speed between the left and right motors. See the document in the same directory: Solution to Not Move Straight</p></section><p>(2) Place the AiNova robot on the line-following map and tap the icon <img loading="lazy" height="94" width="117" src="'+y+'" style="width:70px;"> on the screen to start the function.</p><img loading="lazy" height="541" width="1161" class="common_img" src="'+v+'"><p>If the result is unsatisfactory, refer to &quot;<a href="./.html"><strong>Debugging and Instructional Guidance</strong></a>&quot; for &quot;<a href="./.html"><strong>Line-Following Sensor Sensitivity Adjustment</strong></a>.&quot;</p><h3 id="_4-2-3-draw-to-follow" tabindex="-1">4.2.3 Draw to Follow <a class="header-anchor" href="#_4-2-3-draw-to-follow" aria-label="Permalink to &quot;4.2.3 Draw to Follow&quot;">​</a></h3><p>(1) Tap the corresponding icon <img loading="lazy" height="176" width="146" src="'+w+'" style="width:70px;"> on the main screen to enter the &quot;<strong>Draw to Follow</strong>&quot; interface.</p><img loading="lazy" height="586" width="1269" class="common_img" src="'+x+'"><p>(2) Select a shape you want the robot to follow, for example, Triangle. As shown in the image below. Then tap the icon <img loading="lazy" height="96" width="107" src="'+A+'" style="width:70px;"> to run the program.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The robot may deviate when moving in a straight line. This is due to mechanical bias and is a normal phenomenon. You can reduce the deviation by adjusting the differential speed between the left and right motors. See the document in the same directory: Solution to Not Move Straight</p></section><img loading="lazy" height="449" width="971" class="common_img" src="'+N+'"><h3 id="_4-2-4-intelligent-vision" tabindex="-1">4.2.4 Intelligent Vision <a class="header-anchor" href="#_4-2-4-intelligent-vision" aria-label="Permalink to &quot;4.2.4 Intelligent Vision&quot;">​</a></h3><p>Tap the corresponding icon <img loading="lazy" height="151" width="132" src="'+q+'" style="width:70px;"> on the main screen to enter the &quot;<strong>Intelligent Vision</strong>&quot; interface.</p><p>Games and function descriptions for each icon are listed below:</p><table class="docutils-nobg" border="1"><colgroup><col><col><col></colgroup><tbody><tr><td><strong>Game</strong></td><td><strong>Function</strong></td><td><strong>Note</strong></td></tr><tr><td>Color Tracking</td><td>Run to follow the color block trained in the WonderCam.</td><td><p>Keep the card in the detect range.</p><p>Do not move the card too fast.</p></td></tr><tr><td>Tag Recognition</td><td><p>Recognize the provided AprilTag to run the corresponding actions.</p><p>ID1：Sway left and right</p><p>ID2: Spin around</p><p>ID3: RGB lights blink</p></td><td><p>Ensure good lighting.</p><p>Tags must be undamaged and unfolded.</p></td></tr><tr><td>Road Sign Recognition</td><td>Recognize road sign cards and performs specific responses.</td><td><p>Keep the card still and within the robot&#39;s vision.</p><p>Refer to the example below for correct card orientation.</p></td></tr></tbody></table><h2 id="_4-3-solution-to-not-move-straight" tabindex="-1">4.3 Solution to Not Move Straight <a class="header-anchor" href="#_4-3-solution-to-not-move-straight" aria-label="Permalink to &quot;4.3 Solution to Not Move Straight&quot;">​</a></h2><h3 id="_4-3-1-reason" tabindex="-1">4.3.1 Reason <a class="header-anchor" href="#_4-3-1-reason" aria-label="Permalink to &quot;4.3.1 Reason&quot;">​</a></h3><p>The motor itself has deviations. Though two motors are set to the same speed in the program, their actual speeds may deffer due to the slight deviations caused by internal gear reduction ration. If the left wheel is faster than the right wheel, the robot will veer to the the right. Conversely, if the left wheel is slower than the right wheel, the robot will veer to the left.</p><h3 id="_4-3-2-solution" tabindex="-1">4.3.2 Solution <a class="header-anchor" href="#_4-3-2-solution" aria-label="Permalink to &quot;4.3.2 Solution&quot;">​</a></h3><p>Try to adjust the wheels to have an equal spacing during assembly. When writing the control program, set different speeds for the two wheels to compensate for the inherent errors of the deceleration motor by utilizing the speed difference. The specific method is as follow: when the robot veers to one side, slowly increase the speed of the motor on that side without changing the speed of the other motor until the robot can move in a straight line.</p><img loading="lazy" height="249" width="459" class="common_img" src="'+P+'">',45)])])}const D=e(k,[["render",z]]);export{B as __pageData,D as default};
